-- The language a person reads Backstage in, on their account rather than in the address: a
-- volunteer who reads Chinese and looks after a German team must not have the interface turn
-- German whenever they open that team's pages.
--
-- ITS OWN TABLE, not a column on "user": that table is Better Auth's, generated by its CLI
-- (migrations/0001_auth.sql), and a column it does not know about is a column its
-- regenerate-and-diff workflow would not carry forward. A row per person, created on first
-- save and never before, so the common case writes nothing.
--
-- No row means no choice: the page then reads its `[lang]` segment, as a signed-out visitor's does.
create table "user_setting" (
  "userId"    text        not null primary key references "user" ("id") on delete cascade,
  -- Same shape as every other language code here (language_grant.lang). Not a foreign key:
  -- a language row can be removed while somebody's choice survives, and the setting then
  -- simply reads the fallback.
  "uiLang"    text        check ("uiLang" ~ '^[a-z]{2}[A-Z]{2}$'),
  "updatedAt" timestamptz not null default now()
);
